fn get_column(input: &Vec<Vec<i8>>, j: usize, m: usize, n: usize) -> Vec<i8> {
    // Extract the j-th column by iterating over all n rows
    // For safety, assume input rows have length m as per problem statement
    let mut col = Vec::with_capacity(n);
    for i in 0..n {
        col.push(input[i][j]);
    }
    col
}

fn column_stack(input: Vec<Vec<i8>>, m: usize, n: usize) -> Vec<Vec<i8>> {
    // Create the transposed matrix: m rows with length n each
    let mut result = Vec::with_capacity(m);

    // For each original column index j from 0 to m-1,
    // extract that column and push as a new row in result
    for j in 0..m {
        let col = get_column(&input, j, m, n);
        result.push(col);
    }

    result
}